// Generated by `just generate` from `src/plugins/dotclaude-codegraph/slices/*/slice.ts`. Edit the source and run `just generate`.
import type { On } from "claude-code";
import { onTreeChange as h0 } from "../slices/graph/adapters/mod.ts";

export const register = (on: On): void => {
  // eval: tool.call graph
  on(
    "tool.call",
    {
      tool: "Bash",
      command:
        /(?:^|[;&|])\s*git(?:\s+(?:-[Cc]\s+(?:[^\s"']|"[^"]*"|'[^']*')+|--(?:git-dir|work-tree|namespace)(?:=|\s+)(?:[^\s"']|"[^"]*"|'[^']*')+|--(?!(?:git-dir|work-tree|namespace)(?:=|\s))[a-z][\w-]*|-[pP]))*\s+(?:commit|merge|rebase|pull|checkout|switch|reset|cherry-pick|revert|stash|apply|am)(?:\s|$)/,
    },
    h0,
  );
};

