{
  "description": "dotclaude-codegraph: `slices/graph/adapters/hook.ts` syncs the CodeGraph index at session start and adds one line about the graph, and syncs the index in the background after an `Edit`, a `Write`, or a `git` command that changes the tree. Each hook runs only in a project with a `.codegraph/` index.",
  "modules": ["./register.ts"],
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "bun --no-env-file \"${CLAUDE_PLUGIN_ROOT}/slices/graph/adapters/hook.ts\" session-start",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|MultiEdit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "bun --no-env-file \"${CLAUDE_PLUGIN_ROOT}/slices/graph/adapters/hook.ts\" sync",
            "timeout": 60,
            "async": true
          }
        ]
      }
    ]
  }
}
